<template>
  <section v-if="normalized.length" class="knowledge-sources st-kb">
    <button type="button" class="source-toggle st-kb-toggle" :aria-expanded="open" @click="open=!open"><span class="source-book" aria-hidden="true">▤</span><span>知识库来源<small>{{used.length ? `${used.length} 条已引用` : `${normalized.length} 条检索参考`}}{{used.length&&references.length?` · ${references.length} 条其他参考`:''}}</small></span><span class="source-chevron">{{open?'−':'＋'}}</span></button>
    <div v-if="open" class="source-content">
      <p class="source-note">{{used.length?'以下资料被本条回答引用。':'模型未标明引用编号；以下为本轮实际提供给模型的检索参考。'}}</p>
      <div class="source-grid"><article v-for="s in primary" :key="s.id" :data-campus-entry="s.id" :data-campus-collection="s.collection" class="source-item st-kb-item"><div class="source-top"><span>{{collectionLabel(s.collection)}}</span><small v-if="s.citationId">[{{s.citationId}}]</small><small v-else>{{s.kind==='map'?'地图依据':'管理员约定'}}</small></div><a v-if="safeUrl(s.url)" class="source-title st-kb-title is-link" :href="safeUrl(s.url)" target="_blank" rel="noopener noreferrer">{{shortTitle(s.title)}} <span>↗</span></a><strong v-else class="source-title st-kb-title">{{shortTitle(s.title)}}</strong><p v-if="s.summary" class="source-excerpt">{{s.summary}}</p><div class="source-origin"><span>{{sourceLabel(s.source)}}</span><small>{{trustLabel(s.trust)}}</small></div><details v-if="s.locator || shortTitle(s.title)!==s.title" class="source-location"><summary>查看资料位置</summary><p>{{s.locator || s.title}}</p></details></article></div>
      <template v-if="used.length&&references.length"><button type="button" class="source-more" :aria-expanded="more" @click="more=!more">{{more?'收起':'展开'}}其他检索参考（{{references.length}} 条）<span>{{more?'−':'＋'}}</span></button><p v-if="more" class="source-note">这些资料参与了检索，回答未引用其编号。</p><div v-if="more" class="source-grid"><article v-for="s in references" :key="s.id" :data-campus-entry="s.id" :data-campus-collection="s.collection" class="source-item is-reference"><div class="source-top"><span>{{collectionLabel(s.collection)}}</span><small v-if="s.citationId">[{{s.citationId}}]</small></div><a v-if="safeUrl(s.url)" class="source-title" :href="safeUrl(s.url)" target="_blank" rel="noopener noreferrer">{{shortTitle(s.title)}} ↗</a><strong v-else class="source-title">{{shortTitle(s.title)}}</strong><p v-if="s.summary" class="source-excerpt">{{s.summary}}</p><div class="source-origin">{{sourceLabel(s.source)}}</div></article></div></template>
    </div>
  </section>
</template>
<script setup lang="ts">
import {computed,ref} from 'vue'
import type {KnowledgeSource} from '@/api/chat-stream'
const props=defineProps<{sources?:KnowledgeSource[]}>(),open=ref(false),more=ref(false)
const safeUrl=(url?:string)=>typeof url==='string'&&/^https?:\/\//i.test(url)?url:''
const normalized=computed(()=>{const seen=new Set<string>();return (props.sources||[]).filter(s=>{const key=s.id||s.title;if(!s.title||seen.has(key))return false;seen.add(key);return true})})
const used=computed(()=>normalized.value.filter(s=>s.used)),references=computed(()=>normalized.value.filter(s=>!s.used)),primary=computed(()=>used.value.length?used.value:references.value)
const shortTitle=(title:string)=>title.split(' / ').at(-1)||title
const collectionLabel=(key:string)=>({maps:'校园地图',handbook:'学生手册',portal:'校园门户',services:'一站式服务',matters:'办事指南',courses:'课程资料',freshman:'新生指南',survival:'校园生活',takeout:'餐饮经验'} as Record<string,string>)[key]||(key.startsWith('base:')?'外挂知识库':key||'校园资料')
const sourceLabel=(file:string)=>/UCASSbook/.test(file)?'学生生活手册':/campus-maps/.test(file)?'手绘校园地图':file||'未标注资料名称'
const trustLabel=(trust?:string)=>({handbook:'手册资料',community:'社区整理',reviewed:'已审核',ai_reviewed:'AI 审核资料',official_index:'校内索引',curated:'整理资料'} as Record<string,string>)[trust||'']||''
</script>
<style scoped>
.knowledge-sources{margin:14px 0;border:1px solid var(--nx-border,var(--el-border-color));border-radius:14px;background:var(--nx-surface,var(--el-bg-color));overflow:hidden}.source-toggle{width:100%;display:flex;align-items:center;gap:10px;padding:12px 15px;background:none;border:0;text-align:left;color:var(--nx-text,var(--el-text-color-primary));font:inherit;font-size:12px;cursor:pointer}.source-toggle small{display:block;font-size:10px;color:var(--nx-text-2,var(--el-text-color-secondary));margin-top:4px}.source-book{color:var(--nx-accent,var(--el-color-primary));font-size:22px}.source-chevron{margin-left:auto;color:var(--nx-accent,var(--el-color-primary));font-size:17px}.source-content{padding:0 14px 14px}.source-note{font-size:10px;line-height:1.7;color:var(--nx-text-2,var(--el-text-color-secondary));margin:0 0 10px}.source-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.source-item{display:flex;flex-direction:column;gap:9px;min-width:0;border:1px solid var(--nx-border,var(--el-border-color));border-radius:10px;padding:13px;background:var(--nx-surface-2,var(--el-bg-color))}.source-top,.source-origin{display:flex;justify-content:space-between;gap:8px;align-items:center;color:var(--nx-text-2,var(--el-text-color-secondary));font-size:10px}.source-top>span{padding:3px 6px;border-radius:5px;background:var(--nx-accent-soft,var(--el-color-primary-light-9));color:var(--nx-accent,var(--el-color-primary))}.source-top small{font-size:9px}.source-title{font-size:12px;color:var(--nx-text,var(--el-text-color-primary));font-weight:600;text-decoration:none;line-height:1.6;overflow-wrap:anywhere}.source-title span{font-size:11px;color:var(--nx-accent,var(--el-color-primary))}.source-excerpt{font-size:11px;line-height:1.8;color:var(--nx-text-2,var(--el-text-color-secondary));margin:0;white-space:pre-line;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}.source-origin{margin-top:auto;line-height:1.5;overflow-wrap:anywhere}.source-origin small{flex-shrink:0;font-size:9px}.source-location{font-size:10px;color:var(--nx-text-2,var(--el-text-color-secondary))}.source-location summary{cursor:pointer}.source-location p{line-height:1.6;overflow-wrap:anywhere}.source-more{width:100%;margin-top:12px;border:0;background:none;font:inherit;font-size:11px;color:var(--nx-accent,var(--el-color-primary));text-align:left;padding:8px 0;cursor:pointer}.source-more span{float:right}.source-title.is-link:hover,.source-more:hover{color:var(--nx-accent,var(--el-color-primary));text-decoration:underline}.source-toggle:focus-visible,.source-more:focus-visible,.source-title:focus-visible{outline:2px solid var(--nx-accent,var(--el-color-primary));outline-offset:2px}@media(max-width:600px){.source-grid{grid-template-columns:1fr}.source-item{padding:12px}}
</style>
